(()=>{
'use strict';
const L=WeightLab, el=id=>document.getElementById(id);let experiment=null,proposal=null,run=null,controller=null,responseSource='manual response';
const descriptions={read:'A shuffled, unlabelled network is sampled from the three known families. Ask a model to identify its behavior from weights alone.',repair:'Capture the current playground weights and ask a model to repair them for the selected target. Your manual edits are included.',write:'Ask a model to construct a complete network for the selected target, starting from 17 zeros.'};
const architecture='Two inputs x,y in [-1,1]. Four hidden ReLU units h_i=max(0,W[i][0]*x+W[i][1]*y+b[i]). Output p=sigmoid(sum_i v[i]*h_i + bias). Predict class 1 iff p>0.5. W is 4x2, b and v each length 4; bias scalar. Every parameter must be a finite number in [-100,100].';
function status(text,error=false){el('experiment-status').textContent=text;el('experiment-status').classList.toggle('error',error);}
function invalidate(){if(controller)controller.abort();experiment=null;proposal=null;run=null;el('experiment-prompt').value='';el('model-response').value='';for(const id of ['copy-prompt','run-model','evaluate-response','apply-proposal','download-run'])el(id).disabled=true;el('experiment-results').replaceChildren();status('Settings changed. Prepare a new experiment.');}
function modeDescription(){el('experiment-description').textContent=descriptions[el('experiment-mode').value];}
function prepare(){if(controller)controller.abort();let mode=el('experiment-mode').value,target=key,initial=L.validate(net),truth=null;const randoms=crypto.getRandomValues(new Uint32Array(3));
 if(mode==='read'){target=Object.keys(specs)[randoms[0]%3];truth=target;initial=L.shuffled(L.validate(specs[target]),L.rng(randoms[1]));}else if(mode==='write')initial=L.zeros();
 experiment={id:Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,"0")).join(""),mode,target,initial,truth,seed:randoms[2],instructions:el('experiment-goal').value.trim(),createdAt:new Date().toISOString()};proposal=null;run=null;
 let task=mode==='read'?'Infer the behavior of this network from its raw weights. Choose one label: diagonal (class 1 iff x+y>0), band (class 1 iff abs(x)<0.4), xor (class 1 iff x*y<0). Do not run tools or inference; reason about the arithmetic. Return JSON only: {"label":"diagonal|band|xor","explanation":"your reasoning"}.':`${mode==='repair'?'Repair these weights with as few changes as practical':'Write new weights from this all-zero initialization'} so the network matches this target: ${{diagonal:"Class 1 iff x + y > 0.",band:"Class 1 iff abs(x) < 0.4.",xor:"Class 1 iff x * y < 0."}[target]} Reason directly about the weights; do not use gradient descent or training. Return JSON only: {"weights":{"W":[[0,0],[0,0],[0,0],[0,0]],"b":[0,0,0,0],"v":[0,0,0,0],"bias":0},"explanation":"explain the proposed computation"}. Replace the example zeros with your proposed parameters.`;
 experiment.prompt=[architecture,task,experiment.instructions?'Additional user instructions: '+experiment.instructions:'','Network weights: '+JSON.stringify(initial)].filter(Boolean).join('\n\n');
 el('experiment-prompt').value=experiment.prompt;el('model-response').value='';responseSource='manual response';el('experiment-results').replaceChildren();for(const id of ['copy-prompt','run-model','evaluate-response'])el(id).disabled=false;for(const id of ['apply-proposal','download-run'])el(id).disabled=true;status('Experiment prepared. Send to your model or copy the prompt.');
}
function row(name,value){const r=document.createElement('div');r.className='result-row';const a=document.createElement('span'),b=document.createElement('strong');a.textContent=name;b.textContent=value;r.append(a,b);el('experiment-results').append(r);}
function evaluate(){proposal=null;run=null;el('apply-proposal').disabled=true;el('download-run').disabled=true;el('experiment-results').replaceChildren();try{if(!experiment)throw Error('Prepare an experiment first.');const raw=el('model-response').value;if(raw.length>100000)throw Error('Response is too large (100 KB maximum).');const response=L.parse(raw);if(typeof response.explanation!=='string'||response.explanation.length>20000)throw Error('Include an explanation string (maximum 20,000 characters).');
 run={...L.copy(experiment),response,evaluatedAt:new Date().toISOString(),source:responseSource,evaluation:{}};
 if(experiment.mode==='read'){if(!['diagonal','band','xor'].includes(response.label))throw Error('The label must be diagonal, band, or xor.');const correct=response.label===experiment.truth;row('Prediction',response.label);row('Hidden answer',experiment.truth);row('Result',correct?'Correct':'Incorrect');run.evaluation={correct};}
 else{proposal=L.validate(response.weights);const target=specs[experiment.target].target;const before=L.score(experiment.initial,target,experiment.seed),after=L.score(proposal,target,experiment.seed);run.evaluation={before,after,changed:L.delta(experiment.initial,proposal)};row('Target',experiment.target);row('Baseline agreement',(100*before.agreement).toFixed(2)+'%');row('Proposal agreement',(100*after.agreement).toFixed(2)+'%');row('Change',((after.agreement-before.agreement)*100).toFixed(2)+' percentage points');row('Log loss (lower is better)',before.loss.toFixed(4)+' → '+after.loss.toFixed(4));row('Parameters changed',run.evaluation.changed+' / 17');el('apply-proposal').disabled=false;}
 const p=document.createElement('p');p.className='result-explanation';p.textContent='Model explanation (not independently verified):\n'+response.explanation;el('experiment-results').append(p);el('download-run').disabled=false;status('Evaluation complete. No weights have been applied to the playground.');
 }catch(e){proposal=null;run=null;status(e.message,true);}}
async function send(){if(!experiment)return;try{
 if(el('connection-mode').value==='manual')throw Error('Choose API under Model connection, or copy the prompt into your preferred model.');
 if(location.protocol!=='https:'&&!['localhost','127.0.0.1','[::1]'].includes(location.hostname))throw Error('API calls are disabled on HTTP pages. Open the HTTPS site or run a local copy.');
 const url=new URL(el('api-endpoint').value);const local=['localhost','127.0.0.1','[::1]'].includes(url.hostname);
 if(el('connection-mode').value==='local'&&!local)throw Error('Local mode only permits localhost, 127.0.0.1, or [::1].');
 if(url.protocol!=='https:'&&!(url.protocol==='http:'&&local))throw Error('Use an HTTPS endpoint, or a loopback HTTP server.');
 if(url.username||url.password||url.search||url.hash)throw Error('Use a plain endpoint URL without credentials, query parameters, or fragments.');
 const model=el('api-model').value.trim();if(!model)throw Error('Enter the model identifier.');
 const id=experiment.id,transport=el('connection-mode').value;proposal=null;run=null;el('apply-proposal').disabled=true;el('download-run').disabled=true;el('experiment-results').replaceChildren();controller=new AbortController();const active=controller;el('run-model').disabled=true;el('cancel-model').hidden=false;el('evaluate-response').disabled=true;status('Waiting for your model…');
 const headers={'Content-Type':'application/json'};const secret=el('api-key').value.trim();if(secret)headers.Authorization='Bearer '+secret;
 const timer=setTimeout(()=>active.abort(),120000);
 try{const response=await fetch(url.href,{method:'POST',headers,body:JSON.stringify({model,messages:[{role:'user',content:experiment.prompt}],stream:false}),signal:active.signal,credentials:'omit',redirect:'error'});if(!response.ok)throw Error('Model endpoint returned HTTP '+response.status+'. Check the endpoint, model, key, and provider quota.');const data=await response.json();const content=data.choices?.[0]?.message?.content;if(typeof content!=='string')throw Error('Expected choices[0].message.content from a compatible chat completions endpoint.');if(experiment?.id!==id)return;el('model-response').value=content;responseSource={transport,endpoint:url.origin+url.pathname,model};status('Model response received. Validate and evaluate it before applying.');}
 finally{clearTimeout(timer);if(controller===active){controller=null;el('run-model').disabled=!experiment;el('evaluate-response').disabled=!experiment;el('cancel-model').hidden=true;}}
 }catch(e){status(e.name==='AbortError'?'Request cancelled or exceeded the two-minute timeout.':e instanceof TypeError?'Could not reach the endpoint. Check its URL, CORS policy, and local-network permissions. Manual exchange remains available.':e.message,true);}}
function download(){if(!run)return;const url=URL.createObjectURL(new Blob([JSON.stringify(run,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='weightspace-'+run.mode+'-'+run.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
el('experiment-mode').onchange=()=>{invalidate();modeDescription();};el('experiment-goal').oninput=invalidate;
el('prepare-experiment').onclick=prepare;el('evaluate-response').onclick=evaluate;el('run-model').onclick=send;el('cancel-model').onclick=()=>controller?.abort();el('download-run').onclick=download;
el('model-response').oninput=()=>{responseSource='manual response';proposal=null;run=null;el('apply-proposal').disabled=true;el('download-run').disabled=true;el('experiment-results').replaceChildren();status('Response changed. Evaluate again before applying.');};
el('apply-proposal').onclick=()=>{if(!proposal||!experiment)return;key=experiment.target;el('preset').value=key;net=L.copy(proposal);base=L.copy(experiment.initial);el('description').textContent=specs[key].description;sliders();render();el('status').textContent='● Model proposal applied';status('Evaluated proposal applied. Explore its weights in the playground above.');};
el('copy-prompt').onclick=async()=>{try{await navigator.clipboard.writeText(el('experiment-prompt').value);status('Prompt copied. Paste it into your model, then bring back the JSON.');}catch{el('experiment-prompt').focus();el('experiment-prompt').select();status('Prompt selected. Use your browser’s Copy command.');}};
el('connection-mode').onchange=()=>{const mode=el('connection-mode').value;el('api-settings').hidden=mode==='manual';el('api-key').value='';if(mode==='local'){el('api-endpoint').value='http://localhost:11434/v1/chat/completions';el('api-model').placeholder='Your installed model, e.g. qwen3:8b';}else if(mode==='api'){el('api-endpoint').value='';el('api-model').placeholder='Model available from your provider';}if(location.protocol!=='https:'&&!['localhost','127.0.0.1','[::1]'].includes(location.hostname)){el('api-key').disabled=true;status('Use HTTPS or a local copy for model connections. Manual exchange is available here.',true);}};
// Mark imported model parameters accurately even when they exceed the original slider range.
modeDescription();
})();
